$dir    = $PSScriptRoot
$xray   = "D:\v2rayN-windows-64\bin\xray\xray.exe"
$ip     = "199.180.117.149"
$report = Join-Path $dir "report.txt"
Set-Content $report "报告时间: $(Get-Date)" -Encoding UTF8

function Log($s) { Write-Host $s; Add-Content $report $s -Encoding UTF8 }

Log "`n== 0. 当前网络 =="
Get-NetIPConfiguration | Where-Object { $_.IPv4DefaultGateway } | ForEach-Object {
    Log "$($_.InterfaceAlias)  IP=$($_.IPv4Address.IPAddress)  网关=$($_.IPv4DefaultGateway.NextHop)"
}

Log "`n== 1. 直连 TLS 握手 (不同 SNI, 各 3 次) =="
foreach ($sni in "apps.apple.com", "www.microsoft.com") {
    for ($i = 1; $i -le 3; $i++) {
        $r = curl.exe -s -o NUL -w "connect=%{time_connect}s tls=%{time_appconnect}s http=%{http_code}" -m 10 --noproxy "*" --resolve "${sni}:443:$ip" "https://$sni/" 2>&1
        Log "SNI=$sni #$i  $r  exit=$LASTEXITCODE"
    }
}

Log "`n== 2. Xray 不同指纹对比 =="
foreach ($fp in "firefox", "chrome", "safari", "ios", "edge", "random") {
    $cfg = Join-Path $dir "t-$fp.json"
    $log = Join-Path $dir "t-$fp.log"
    $c = Get-Content (Join-Path $dir "debug.json") -Raw | ConvertFrom-Json
    $c.outbounds[0].streamSettings.realitySettings.fingerprint = $fp
    $c | ConvertTo-Json -Depth 20 | Set-Content $cfg -Encoding ASCII
    $p = Start-Process $xray -ArgumentList "run -c `"$cfg`"" -RedirectStandardOutput $log -RedirectStandardError "$log.err" -PassThru -WindowStyle Hidden
    Start-Sleep 2
    $r = curl.exe -s -o NUL -w "http=%{http_code} 耗时=%{time_total}s" -m 12 -x socks5h://127.0.0.1:10899 https://www.google.com/generate_204 2>&1
    Stop-Process $p -Force -ErrorAction SilentlyContinue
    Start-Sleep 1
    Log "fp=$fp  $r"
    Get-Content $log -ErrorAction SilentlyContinue | Select-String "REALITY|failed to process" | Select-Object -Last 2 | ForEach-Object { Log "    $_" }
}

Log "`n完成。报告: $report"

